@namespace sv_d7eefd542abc4eb295b6492e41149206.Components.Pages.Settings

<nav class="settings-sidebar">
    <h3 class="sidebar-title">Settings</h3>
    <ul class="sidebar-nav">
        @foreach (var section in Sections)
        {
            <li class="@(section == ActiveSection ? "active" : "")" @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="nav-icon">@GetIcon(section)</span>
                <span class="nav-label">@section</span>
            </li>
        }
    </ul>
</nav>

@code {
    [Parameter] public string ActiveSection { get; set; } = "Profile";
    [Parameter] public EventCallback<string> OnSectionChanged { get; set; }

    private static readonly string[] Sections = { "Profile", "Notifications", "Security", "Appearance" };

    private string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

@namespace sv_d7eefd542abc4eb295b6492e41149206.Components.Pages.Settings
@using sv_d7eefd542abc4eb295b6492e41149206.Models

<div class="settings-section">
    <h2>Profile</h2>

    <div class="avatar-preview">
        <img src="@AvatarUrl" alt="Avatar" class="avatar-img" />
        <p class="avatar-url">@AvatarUrl</p>
    </div>

    <div class="form-group">
        <label for="displayName">Display Name</label>
        <input id="displayName" type="text" @bind="DisplayName" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="email">Email</label>
        <input id="email" type="email" @bind="Email" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="bio">Bio</label>
        <textarea id="bio" rows="4" @bind="Bio" @bind:event="oninput"></textarea>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save Changes</button>
        <button class="btn btn-secondary" @onclick="Discard">Discard Changes</button>
    </div>

    @if (!string.IsNullOrEmpty(_statusMessage))
    {
        <div class="toast-message @_statusClass">@_statusMessage</div>
    }
</div>

@code {
    [Parameter] public UserProfile? Profile { get; set; }
    [Parameter] public EventCallback<UserProfile> OnSave { get; set; }

    private string DisplayName { get; set; } = "";
    private string Email { get; set; } = "";
    private string AvatarUrl { get; set; } = "";
    private string Bio { get; set; } = "";

    private string _statusMessage = "";
    private string _statusClass = "";

    protected override void OnParametersSet()
    {
        if (Profile is not null && string.IsNullOrEmpty(DisplayName) && _statusMessage == "")
        {
            LoadFromProfile();
        }
    }

    private void LoadFromProfile()
    {
        if (Profile is null) return;
        DisplayName = Profile.DisplayName;
        Email = Profile.Email;
        AvatarUrl = Profile.AvatarUrl;
        Bio = Profile.Bio;
    }

    private async Task SaveAsync()
    {
        var updated = new UserProfile(DisplayName, Email, AvatarUrl, Bio);
        await OnSave.InvokeAsync(updated);
        _statusMessage = "Profile saved successfully!";
        _statusClass = "toast-success";
        StateHasChanged();
        _ = ClearMessageAfterDelay();
    }

    private void Discard()
    {
        LoadFromProfile();
        _statusMessage = "Changes discarded.";
        _statusClass = "toast-info";
        _ = ClearMessageAfterDelay();
    }

    private async Task ClearMessageAfterDelay()
    {
        await Task.Delay(3000);
        _statusMessage = "";
        StateHasChanged();
    }
}

@namespace sv_d7eefd542abc4eb295b6492e41149206.Components.Pages.Settings
