<div class="settings-section">
    <h2>Notifications</h2>

    <div class="toggle-group">
        <label class="toggle-item">
            <input type="checkbox" checked="@EmailNotifications" @onchange="e => EmailNotifications = (bool)e.Value!" />
            <span>Email Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" checked="@PushNotifications" @onchange="e => PushNotifications = (bool)e.Value!" />
            <span>Push Notifications</span>
        </label>

        <label class="toggle-item">
            <input type="checkbox" checked="@WeeklyDigest" @onchange="e => WeeklyDigest = (bool)e.Value!" />
            <span>Weekly Digest</span>
        </label>
    </div>

    <h3>Muted Channels</h3>
    <div class="channel-list">
        @foreach (var channel in AllChannels)
        {
            <label class="channel-item">
                <input type="checkbox" checked="@IsMuted(channel)" @onchange="e => ToggleMute(channel, (bool)e.Value!)" />
                <span>#@channel</span>
            </label>
