<div class="settings-section">
    <h2>Security</h2>

    <!-- Change Password Panel -->
    <div class="expandable-panel">
        <button class="panel-header" @onclick="() => _passwordExpanded = !_passwordExpanded">
            <span>🔑 Change Password</span>
            <span class="expand-icon">@(_passwordExpanded ? "▼" : "▶")</span>
        </button>

        @if (_passwordExpanded)
        {
            <div class="panel-content">
                <div class="form-group">
                    <label for="currentPwd">Current Password</label>
                    <input id="currentPwd" type="password" @bind="_currentPassword" />
                </div>
                <div class="form-group">
                    <label for="newPwd">New Password</label>
                    <input id="newPwd" type="password" @bind="_newPassword" />
                </div>
                <div class="form-group">
                    <label for="confirmPwd">Confirm Password</label>
                    <input id="confirmPwd" type="password" @bind="_confirmPassword" />
                </div>
                @if (!string.IsNullOrEmpty(_passwordError))
                {
                    <p class="error-message">@_passwordError</p>
                }
                @if (!string.IsNullOrEmpty(_passwordSuccess))
                {
                    <p class="success-message">@_passwordSuccess</p>
                }
                <button class="btn btn-primary" @onclick="UpdatePasswordAsync">Update Password</button>
            </div>
        }
    </div>

    <!-- Two-Factor Authentication -->
    <div class="tfa-section">
        <h3>Two-Factor Authentication</h3>
        <div class="tfa-status">
            <span class="status-indicator @(Settings?.TwoFactorEnabled == true ? "status-on" : "status-off")"></span>
            <span>@(Settings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")</span>
            <label class="toggle-item tfa-toggle">
                <input type="checkbox" checked="@(Settings?.TwoFactorEnabled ?? false)" @onchange="Toggle2FA" />
                <span>Toggle</span>
            </label>
        </div>
        @if (Settings?.LastPasswordChange is not null)
        {
            <p class="last-changed">Last password change: @Settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
        }
    </div>

    <!-- Active Sessions -->
    <div class="sessions-section">
        <h3>Active Sessions</h3>
        @if (Settings?.Sessions is not null)
        {
            <table class="sessions-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Settings.Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != "current")
                                {
                                    <button class="btn btn-danger btn-sm" @onclick="() => PromptRevoke(session)">Revoke</button>
                                }
                                else
                                {
                                    <span class="current-badge">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        }
    </div>

    <!-- Revoke Confirmation Dialog -->
    @if (_sessionToRevoke is not null)
    {
        <div class="modal-overlay" @onclick="CancelRevoke">
            <div class="modal-dialog" @onclick:stopPropagation="true">
                <h4>Revoke Session</h4>
                <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                <div class="modal-actions">
                    <button class="btn btn-danger" @onclick="ConfirmRevokeAsync">Revoke</button>
                    <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public SecuritySettings? Settings { get; set; }
    [Parameter] public EventCallback<string> OnRevokeSession { get; set; }
    [Parameter] public EventCallback<(string currentPassword, string newPassword)> OnChangePassword { get; set; }
    [Parameter] public EventCallback<bool> OnToggle2FA { get; set; }

    private bool _passwordExpanded;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private string _passwordError = "";
    private string _passwordSuccess = "";
    private ActiveSession? _sessionToRevoke;

    private async Task UpdatePasswordAsync()
    {
        _passwordError = "";
        _passwordSuccess = "";

        if (string.IsNullOrWhiteSpace(_currentPassword) || string.IsNullOrWhiteSpace(_newPassword))
        {
            _passwordError = "All fields are required.";
            return;
        }

        if (_newPassword != _confirmPassword)
        {
            _passwordError = "New password and confirmation do not match.";
            return;
        }

        await OnChangePassword.InvokeAsync((_currentPassword, _newPassword));
        _passwordSuccess = "Password updated successfully!";
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
    }

    private async Task Toggle2FA(ChangeEventArgs e)
    {
        var enabled = (bool)e.Value!;
        await OnToggle2FA.InvokeAsync(enabled);
    }

    private void PromptRevoke(ActiveSession session) => _sessionToRevoke = session;

    private void CancelRevoke() => _sessionToRevoke = null;

    private async Task ConfirmRevokeAsync()
    {
        if (_sessionToRevoke is not null)
        {
            await OnRevokeSession.InvokeAsync(_sessionToRevoke.Id);
            _sessionToRevoke = null;
        }
    }

    private string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 5) return "Just now";
        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours} hours ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_d7eefd542abc4eb295b6492e41149206.Components.Pages.Settings
@using sv_d7eefd542abc4eb295b6492e41149206.Models

<div class="settings-section">
    <h2>Appearance</h2>

    <!-- Theme -->
    <div class="form-group">
        <label>Theme</label>
        <div class="radio-group">
            @foreach (var theme in new[] { "Light", "Dark", "System" })
            {
                <label class="radio-item">
                    <input type="radio" name="theme" value="@theme" checked="@(Theme == theme)" @onchange="() => Theme = theme" />
                    <span>@theme</span>
                </label>
            }
        </div>
    </div>

    <!-- Font Size -->
    <div class="form-group">
        <label>Font Size</label>
        <div class="radio-group">
            @foreach (var size in new[] { "Small", "Medium", "Large" })
            {
                <label class="radio-item">
                    <input type="radio" name="fontSize" value="@size" checked="@(FontSize == size)" @onchange="() => FontSize = size" />
                    <span>@size</span>
                </label>
            }
        </div>
    </div>

    <!-- Language -->
    <div class="form-group">
        <label for="language">Language</label>
        <select id="language" @bind="Language">
            <option value="English">English</option>
            <option value="Spanish">Spanish</option>
            <option value="French">French</option>
            <option value="German">German</option>
            <option value="Japanese">Japanese</option>
        </select>
    </div>

    <!-- Compact Mode -->
    <div class="form-group">
        <label class="toggle-item">
            <input type="checkbox" checked="@CompactMode" @onchange="e => CompactMode = (bool)e.Value!" />
            <span>Compact Mode</span>
        </label>
    </div>

    <!-- Live Preview -->
    <div class="preview-area @GetPreviewClasses()">
        <h4>Live Preview</h4>
        <p>This is how your content will look with the selected settings.</p>
        <div class="preview-card">
            <strong>Sample Card</strong>
            <p>A preview of the chosen theme, font size, and layout density.</p>
            <button class="btn btn-primary">Action Button</button>
        </div>
    </div>

    <div class="form-actions">
        <button class="btn btn-primary" @onclick="SaveAsync">Save</button>
    </div>
</div>

@code {
    [Parameter] public AppearanceSettings? Settings { get; set; }
    [Parameter] public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string Theme { get; set; } = "Light";
    private string FontSize { get; set; } = "Medium";
    private string Language { get; set; } = "English";
    private bool CompactMode { get; set; }

    protected override void OnParametersSet()
    {
        if (Settings is not null)
        {
            Theme = Settings.Theme;
            FontSize = Settings.FontSize;
            Language = Settings.Language;
            CompactMode = Settings.CompactMode;
        }
    }

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{Theme.ToLowerInvariant()} preview-font-{FontSize.ToLowerInvariant()}";
        if (CompactMode) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAsync()
    {
        var updated = new AppearanceSettings(Theme, FontSize, Language, CompactMode);
        await OnSave.InvokeAsync(updated);
    }
}

@namespace sv_d7eefd542abc4eb295b6492e41149206.Components.Pages.Settings

<nav class="settings-sidebar">
