.settings-sidebar {
    width: 220px;
    flex-shrink: 0;
}

.sidebar-title {
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: 1rem;
    padding: 0 0.75rem;
    color: #1a1a2e;
}

.sidebar-nav {
    list-style: none;
    padding: 0;
    margin: 0;
}

.sidebar-nav li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem;
    border-radius: 8px;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    color: #555;
    font-weight: 500;
}

.sidebar-nav li:hover {
    background-color: #f0f0f5;
    color: #1a1a2e;
}

.sidebar-nav li.active {
    background-color: #e8e0ff;
    color: #5b21b6;
