}

.panel-header {
    width: 100%;
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 0.85rem 1rem;
    background: #f9fafb;
    border: none;
    cursor: pointer;
    font-size: 0.95rem;
    font-weight: 500;
    color: #374151;
}

.panel-header:hover {
    background: #f3f4f6;
}

.expand-icon {
    font-size: 0.75rem;
}

.panel-content {
    padding: 1.25rem;
    border-top: 1px solid #e5e7eb;
}

/* Error/Success Messages */
.error-message {
    color: #dc2626;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

.success-message {
    color: #059669;
    font-size: 0.85rem;
    margin-bottom: 0.75rem;
}

/* 2FA Section */
.tfa-section {
    margin-bottom: 1.5rem;
}

.tfa-status {
    display: flex;
    align-items: center;
    gap: 0.6rem;
}

.status-indicator {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.status-on {
    background-color: #10b981;
}

.status-off {
    background-color: #ef4444;
}

.tfa-toggle {
    margin-left: 1rem;
}

.last-changed {
    font-size: 0.85rem;
    color: #6b7280;
    margin-top: 0.5rem;
}

/* Sessions Table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e5e7eb;
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 600;
    color: #374151;
    background: #f9fafb;
}

.current-badge {
    font-size: 0.75rem;
    background: #dbeafe;
    color: #1e40af;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
    font-weight: 500;
}

/* Modal */
.modal-overlay {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.modal-dialog {
    background: white;
    border-radius: 12px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
}

.modal-dialog h4 {
    margin: 0 0 0.75rem;
    color: #1a1a2e;
}

.modal-dialog p {
    color: #555;
    font-size: 0.9rem;
    margin-bottom: 1.25rem;
}

.modal-actions {
    display: flex;
    gap: 0.75rem;
    justify-content: flex-end;
}

/* Radio Group */
.radio-group {
    display: flex;
    gap: 1.25rem;
}

.radio-item {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-weight: 500;
    color: #374151;
}

.radio-item input[type="radio"] {
    accent-color: #7c3aed;
}

/* Appearance Preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.5rem;
    border: 2px dashed #d1d5db;
    border-radius: 10px;
    transition: all 0.25s ease;
}

.preview-area h4 {
    margin: 0 0 0.5rem;
}

.preview-card {
    margin-top: 1rem;
    padding: 1rem;
    border-radius: 8px;
    background: #f9fafb;
    border: 1px solid #e5e7eb;
}

.preview-card p {
    font-size: 0.9rem;
    color: #555;
    margin: 0.5rem 0;
}

/* Theme previews */
.preview-theme-dark {
    background-color: #1f2937;
    color: #f9fafb;
    border-color: #4b5563;
}

.preview-theme-dark .preview-card {
    background: #374151;
    border-color: #4b5563;
    color: #e5e7eb;
}

.preview-theme-dark .preview-card p {
    color: #d1d5db;
}

.preview-theme-light {
    background-color: #ffffff;
    color: #1a1a2e;
}

.preview-theme-system {
    background: linear-gradient(135deg, #ffffff 50%, #1f2937 50%);
    color: #1a1a2e;
}

/* Font size previews */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.75rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.5rem;
}

/* Loading */
.loading {
    color: #6b7280;
    font-style: italic;
    padding: 2rem;
}
